INSERT INTO site_settings (id, site_title_vi, site_description_vi, seo_keywords_vi, og_image_url, twitter_handle, github_url, linkedin_url, email, created_at, updated_at, site_title_en, site_description_en, seo_keywords_en, resume_url, phone) VALUES (1, 'Trần Minh Hiểu | AI Software Engineer', 'AI Software Engineer định hướng Nghiên cứu & Kỹ nghệ Giải pháp AI (Applied AI Research & Engineering). Chuyên sâu về Graph Neural Networks, Advanced RAG, Hybrid Search và kiến trúc phần mềm AI thực tế.', 'Trần Minh Hiểu,Tran Minh Hieu,AI Software Engineer,Applied AI Researcher,Graph Neural Networks,Representation Learning,Advanced RAG,Hybrid Search,FastAPI,PyTorch Geometric,Python,Portfolio', '', '', 'https://github.com/Tmh3101', 'https://linkedin.com/in/tmh3101', 'hieutm.site@gmail.com', '2026-03-15T17:03:18.365486+00:00', '2026-09-30T15:57:53.477858+00:00', 'Tran Minh Hieu | AI Software Engineer', 'AI Software Engineer specializing in Applied AI Research & Engineering. Bridging theoretical machine learning (Graph Neural Networks, Advanced RAG, Representation Learning) with production software engineering.', 'Tran Minh Hieu,AI Software Engineer,Applied AI Researcher,Graph Neural Networks,Representation Learning,Advanced RAG,Hybrid Search,FastAPI,PyTorch Geometric,Python,Portfolio', 'https://uhhmsyhsbcvfvilphwdk.supabase.co/storage/v1/object/public/portfolio-assets/cv/CV_TranMinhHieu.pdf', NULL);
INSERT INTO hero_section (id, greeting_vi, name, headline_vi, subheadline_vi, roles_vi, avatar_url, cta_primary_label_vi, cta_primary_href, cta_secondary_label_vi, cta_secondary_href, created_at, updated_at, greeting_en, headline_en, subheadline_en, roles_en, cta_primary_label_en, cta_secondary_label_en, subtitle_vi, subtitle_en, role1_label_vi, role1_label_en, role2_label_vi, role2_label_en, role3_label_vi, role3_label_en) VALUES (1, 'Xin chào, tôi là', 'Trần Minh Hiểu', 'AI Software Engineer', 'Tôi nghiên cứu chuyên sâu các giải pháp Trí tuệ Nhân tạo và hiện thực hóa chúng thành các hệ thống phần mềm thực tế — từ Graph Neural Networks, Advanced RAG đến kiến trúc phân tầng hiệu năng cao.', 'AI / Software,Đại học Cần Thơ,Khoa học máy tính', '/avatars/hieutm.jpg', 'Xem CV', 'https://uhhmsyhsbcvfvilphwdk.supabase.co/storage/v1/object/public/portfolio-assets/cv/CV_TranMinhHieu.pdf', 'Liên hệ', '#contact', '2026-03-15T17:07:04.237823+00:00', '2026-09-30T15:57:53.211297+00:00', 'Hi, I am', 'AI Software Engineer', 'I research advanced Artificial Intelligence architectures and engineer them into robust, production-grade systems — from Graph Neural Networks and Advanced RAG to high-throughput layered software.', 'AI / Software,Can Tho University,Computer Science', NULL, NULL, 'Nghiên cứu & Kỹ nghệ Giải pháp AI Thực chiến', 'Applied AI Research & Engineering', 'Tập trung', 'Focus', 'Tốt nghiệp', 'Graduated', 'Chuyên ngành', 'Major');
INSERT INTO experience_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, current_role_label_vi, current_role_label_en, earlier_roles_label_vi, earlier_roles_label_en, earlier_roles_copy_vi, earlier_roles_copy_en, education_label_vi, education_label_en, highlights_label_vi, highlights_label_en, created_at, updated_at) VALUES (1, 'Hành trình', 'Journey', 'Kinh nghiệm', 'Professional', 'làm việc', 'Experience', 'Hành trình từ khi còn là sinh viên đến khi trở thành Backend Developer, tập trung vào việc xây dựng các hệ thống ổn định và có khả năng mở rộng.', 'A journey from student years to Backend Developer, focusing on building stable and scalable systems.', 'Vai trò hiện tại', 'Current role', 'Các chặng trước', 'Earlier roles', 'Những vai trò trước đó tạo nền cho cách tôi xây backend systems hôm nay.', 'The earlier roles that shaped how I approach backend systems today.', 'Học vấn', 'Education', 'Điểm chính', 'Highlights', '2026-03-17T07:48:51.662793+00:00', '2026-03-17T07:48:51.662793+00:00');
INSERT INTO skill_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, created_at, updated_at) VALUES (1, 'Kỹ năng', 'Skills', 'Công nghệ tôi dùng', 'Tech I work with', 'tôi sử dụng', 'Stack', 'Ngôn ngữ, framework, database và công cụ cloud tôi dùng để ship sản phẩm backend & AI.', 'Languages, frameworks, databases and cloud tooling I use to ship backend & AI products.', '2026-03-17T06:15:44.607856+00:00', '2026-08-16T07:51:38.152029+00:00');
INSERT INTO approach_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, note_label_vi, note_label_en, note_vi, note_en, created_at, updated_at) VALUES (1, 'ABOUT & RESEARCH DIRECTION', 'ABOUT & RESEARCH DIRECTION', 'Nghiên cứu & Kỹ nghệ', 'AI Software Engineering &', 'Giải pháp AI', 'Applied Research', 'Tôi là một AI Software Engineer tập trung vào việc nghiên cứu chuyên sâu các giải pháp Trí tuệ Nhân tạo và hiện thực hóa chúng thành các hệ thống phần mềm thực tế, ổn định và có thể mở rộng. Thế mạnh của tôi nằm ở sự kết hợp giữa tư duy nghiên cứu mô hình học máy (Graph Neural Networks, RAG nâng cao, Representation Learning) và kỹ nghệ phần mềm chuẩn mực (Kiến trúc phân tầng, API Type-safe, xử lý dữ liệu bất đồng bộ). Tôi hướng đến việc giải quyết các bài toán kỹ thuật phức tạp thông qua các thiết kế giải pháp có cơ sở toán học và thực nghiệm vững chắc.', 'I am an AI Software Engineer dedicated to researching advanced Artificial Intelligence solutions and architecting them into robust, production-grade software systems. My core strength bridges the gap between theoretical machine learning research (Graph Neural Networks, Advanced RAG, Representation Learning) and disciplined software engineering (Layered architectures, type-safe API contracts, asynchronous task pipelines). I focus on solving complex engineering bottlenecks through mathematically sound and empirically validated AI architectures.', 'ROLE & ĐỊNH HƯỚNG MỤC TIÊU', 'TARGET ROLE & VISION', 'AI Software Engineer / Applied AI Researcher tại các trung tâm R&D, phòng nghiên cứu AI hoặc các công ty công nghệ tiên phong, nơi cần kỹ sư vừa có khả năng nghiên cứu, thử nghiệm và tối ưu các thuật toán AI phức tạp, vừa có năng lực xây dựng sản phẩm phần mềm chuẩn production.', 'AI Software Engineer / Applied AI Researcher in AI R&D labs, quantitative engineering teams, or tech-forward companies where success demands both rigorous algorithmic research and production-quality software development.', '2026-03-17T05:56:08.169847+00:00', '2026-09-30T15:57:51.36642+00:00');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (2, 'Nghiên cứu Kiến trúc Mô hình & Graph AI', 'MODEL RESEARCH & GRAPH NEURAL NETWORKS', 'Nghiên cứu chuyên sâu về học biểu diễn đồ thị (Representation Learning) và Mạng nơ-ron đồ thị (GATv2, Graph Autoencoders). Tiên phong áp dụng kiến trúc tách rời (Decoupled GNN-ML) để khắc phục hiện tượng Over-smoothing trên đồ thị nhiều tầng và xử lý bài toán mất cân bằng dữ liệu nghiêm trọng; đồng thời tích hợp Explainable AI (XAI) nhằm giải mã cơ chế Attention Weights trong thực tế.', '', 0, '2026-03-17T05:59:15.492065+00:00', '2026-09-30T15:57:52.280607+00:00', 'Model Architecture & Graph AI', 'MODEL RESEARCH & GRAPH NEURAL NETWORKS', 'In-depth research on graph representation learning and Graph Neural Networks (GATv2, Graph Autoencoders). Pioneering decoupled GNN-ML architectures to overcome over-smoothing on dense multilayer graphs and solve severe class imbalance; integrating Explainable AI (XAI) to visualize dynamic attention weights for transparent decisions.');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (3, 'Tối ưu hóa Hệ thống Truy xuất & RAG Nâng cao', 'ADVANCED RETRIEVAL & LLM OPTIMIZATION', 'Nghiên cứu và thực nghiệm đối kháng giữa các kỹ thuật truy xuất ngữ nghĩa (Vanilla RAG so với HyDE RAG). Xây dựng giải pháp Hybrid Search kết hợp giữa Vector Embeddings (pgvector) và Sparse Search (BM25) qua thuật toán Reciprocal Rank Fusion; nghiên cứu chiến lược Document Chunking, Context Compression và Fine-tuning mô hình ngôn ngữ mở (Qwen2.5) cho bài toán chuyên biệt.', '', 1, '2026-03-17T05:59:58.41027+00:00', '2026-09-30T15:57:52.804878+00:00', 'Advanced Retrieval & RAG Research', 'ADVANCED RETRIEVAL & LLM OPTIMIZATION', 'Empirical research comparing retrieval architectures (Vanilla RAG vs. HyDE RAG). Engineering hybrid retrieval combining dense vector embeddings (pgvector) with sparse BM25 indexing via Reciprocal Rank Fusion; optimizing document chunking, context compression, and fine-tuning open-source LLMs (Qwen2.5) for domain-specific context.');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (4, 'Kỹ nghệ Phần mềm & Serving Hệ thống AI', 'AI SOFTWARE ENGINEERING & PRODUCTION SERVING', 'Đưa các mô hình nghiên cứu ra môi trường thực tiễn thông qua việc xây dựng các API hiệu năng cao (FastAPI, Next.js), đóng gói containerized (Docker) và tích hợp hàng đợi xử lý ngầm (Redis, BullMQ). Đảm bảo các giải pháp AI vận hành với độ trễ tối ưu, tính nhất quán dữ liệu cao và khả năng phục vụ đồng thời.', '', 2, '2026-03-17T06:00:21.343968+00:00', '2026-09-30T15:57:53.070776+00:00', 'AI Software Engineering & Production Serving', 'AI SOFTWARE ENGINEERING & PRODUCTION SERVING', 'Translating experimental AI models into scalable production systems using high-performance web frameworks (FastAPI, Next.js), containerization (Docker), and asynchronous background queues (Redis, BullMQ). Ensuring end-to-end reliability, low P99 inference latency, and consistent data integrity.');
