INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (3, 'vielora', 'Vielora', 'Nền tảng AI Chatbot SaaS multi-tenant & RAG Pipeline', 'Kiến trúc multi-tenant workspace, Hybrid Search (pgvector + full-text PostgreSQL), hàng đợi cào dữ liệu bất đồng bộ (Redis/BullMQ), thanh toán tự động payOS & hóa đơn điện tử EasyInvoice.', '/assets/optimized/vielora.webp', NULL, 'https://vielora.vn', 'Next.js,TypeScript,Supabase,Redis,BullMQ,Docker,pgvector', true, 0, '2026-08-16T07:51:47.579392+00:00', '2026-09-30T09:21:53.542965+00:00', 'Vielora', 'Multi-tenant AI Chatbot SaaS & RAG Pipeline', 'Multi-tenant workspace architecture, Hybrid Search (pgvector + PostgreSQL full-text), async crawl queue (Redis/BullMQ), automated payOS checkout & EasyInvoice VAT generation.', NULL, 'Multi-tenant,Hybrid Search,Async Queue,payOS & EasyInvoice', 'Multi-tenant,Hybrid Search,Async Queue,payOS & EasyInvoice', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (4, 'xpervia', 'Xpervia', 'Nền tảng quản lý học tập & AI Chatbot RAG', 'LMS với RBAC đầy đủ, thử nghiệm đối sánh Vanilla RAG vs. HyDE RAG, fine-tune Qwen2.5-1.5B và bộ gợi ý khóa học lai (Collaborative + Content-based filtering).', '/assets/optimized/xpervia.webp', 'https://github.com/Tmh3101/xpervia', 'https://xpervia.vercel.app', 'Django,DRF,PostgreSQL,Supabase,Next.js,LangChain,Qwen2.5', false, 4, '2026-08-16T07:51:47.579392+00:00', '2026-09-30T09:21:54.490759+00:00', 'Xpervia', 'Learning Management System & AI RAG Chatbot', 'Full LMS with RBAC, comparative evaluation of Vanilla RAG vs. HyDE RAG, fine-tuned Qwen2.5-1.5B, and hybrid recommender system (Collaborative + Content-based filtering).', NULL, 'Vanilla vs HyDE RAG,Qwen2.5-1.5B Fine-tuning,Hybrid Recommender,RBAC', 'Vanilla vs HyDE RAG,Qwen2.5-1.5B Fine-tuning,Hybrid Recommender,RBAC', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (5, 'sybilsignal', 'SybilSignal', 'Phát hiện gian lận Web3 bằng GNN (Khóa luận 9.8/10)', 'Kiến trúc Decoupled GATv2 + Random Forest xử lý hàng triệu bản ghi on-chain BigQuery, khắc phục over-smoothing và mất cân bằng nhãn. Dashboard XAI attention weights thời gian thực. Điểm khóa luận 9.8/10.', '/assets/optimized/sybilsignal.webp', 'https://github.com/Tmh3101/sybilsignal-app', 'https://sybilsignal.vercel.app', 'Python,PyTorch Geometric,FastAPI,Modal,BigQuery,Next.js', true, 2, '2026-08-16T07:51:47.579392+00:00', '2026-09-30T09:21:54.068201+00:00', 'SybilSignal', 'Graph-based Web3 Fraud Detection (Thesis 9.8/10)', 'Decoupled GATv2 + Random Forest architecture on millions of BigQuery on-chain records, resolving over-smoothing and label imbalance. Real-time XAI attention weights dashboard. Thesis score 9.8/10.', NULL, 'GATv2 Graph Neural Network,Decoupled GNN-ML,XAI Attention Weights,BigQuery Pipeline', 'GATv2 Graph Neural Network,Decoupled GNN-ML,XAI Attention Weights,BigQuery Pipeline', 'https://drive.google.com/file/d/1YOmJeSeUQA0xQq--tOlI6aosKq5rHam8/view?usp=sharing');
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (6, 'slice-socialfi', 'Slice SocialFi', 'Cầu nối Token Cross-chain & Xử lý giao dịch tài chính số', 'Cầu nối token xuyên chuỗi (BNB Chain ↔ LensChain) cơ chế Lock/Mint & Burn/Unlock. Hàng đợi task Redis xử lý giao dịch DNPAY Fiat-to-Crypto bảo đảm zero-data-loss. Container hóa microservices trên AWS EC2.', '/assets/optimized/slice-socialfi.webp', NULL, 'https://slicefi.xyz/', 'Node.js,Hono,Viem,Solidity,PostgreSQL,Redis,AWS EC2,Docker', true, 1, '2026-09-30T09:21:55.037857+00:00', '2026-09-30T09:30:28.457335+00:00', 'Slice SocialFi', 'Cross-chain Token Bridge & Async Transaction Processing', 'Cross-chain token bridge (BNB Chain ↔ LensChain) with Lock/Mint & Burn/Unlock. Redis task queue handling DNPAY Fiat-to-Crypto transaction flow ensuring zero-data-loss. Docker microservices on AWS EC2.', NULL, 'Cross-chain Token Bridge,Zero-data-loss Redis Queue,DNPAY Fiat-to-Crypto,AWS EC2', 'Cross-chain Token Bridge,Zero-data-loss Redis Queue,DNPAY Fiat-to-Crypto,AWS EC2', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (7, 'giftcards', 'Giftcards.vn', 'Giải pháp quà tặng doanh nghiệp & Cổng thanh toán', 'Tích hợp cổng thanh toán DNPAY Merchant, thiết kế cơ chế retry payment flow giảm thiểu tỷ lệ rớt đơn hàng, quản lý vòng đời đơn hàng quà tặng doanh nghiệp.', '/assets/optimized/giftcards.webp', NULL, NULL, 'NestJS,MongoDB,Redis,ReactJS', false, 3, '2026-09-30T09:21:55.431521+00:00', '2026-09-30T09:21:55.431521+00:00', 'Giftcards.vn', 'Corporate Gift Solutions & Payment Gateway', 'Integrated DNPAY Merchant payment gateway, designed payment retry mechanism minimizing cart abandonment rate, managed corporate gift order lifecycle.', NULL, 'DNPAY Merchant Gateway,Payment Retry Flow,Order Lifecycle Management', 'DNPAY Merchant Gateway,Payment Retry Flow,Order Lifecycle Management', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (8, 'identity-service', 'Identity Service', 'Hệ thống định danh & phân quyền bảo mật cao', 'Kiến trúc phân tầng chuẩn mực OOP, xác thực JWT + OAuth2, bảo vệ chống brute-force, refresh token rotation và danh sách thu hồi token (Token Revocation List).', '/assets/optimized/identity-service.webp', 'https://github.com/Tmh3101/user-service', NULL, 'Java 17,Spring Boot 3,Spring Security,MySQL,Redis,Docker', false, 5, '2026-09-30T09:21:55.860191+00:00', '2026-09-30T09:21:55.860191+00:00', 'Identity Service', 'High-Security Enterprise Auth Microservice', 'Layered OOP architecture, JWT + OAuth2 authentication, brute-force protection, refresh token rotation, and token revocation list preventing unauthorized token reuse.', NULL, 'JWT + OAuth2 Auth,Brute-force Protection,Token Revocation List,Layered Architecture', 'JWT + OAuth2 Auth,Brute-force Protection,Token Revocation List,Layered Architecture', NULL);
