INSERT INTO experiences (id, company, role_vi, location_vi, start_date, end_date, is_current, description_vi, highlights_vi, technologies, sort_order, created_at, updated_at, role_en, location_en, description_en, highlights_en, type) VALUES (3, 'TITOPS VIETNAM CO., LTD.', 'AI Software Engineer', 'Việt Nam', '2026-01-01', NULL, true, 'Vielora - Nền tảng AI Chatbot SaaS cho website. Thiết kế RAG pipeline (Gemini + pgvector), kiến trúc multi-tenant, queue bất đồng bộ (Redis/BullMQ), tích hợp thanh toán.', 'Thiết kế RAG end-to-end với hybrid search (full-text + vector),Kiến trúc multi-tenant workspace + REST API bảo mật (CORS, Rate Limiting, FingerprintJS),Queue bất đồng bộ crawl/index/cron email', 'Next.js 14,TypeScript,Supabase,Redis,BullMQ,payOS,Docker,Puppeteer', 0, '2026-08-16T06:39:44.423112+00:00', '2026-09-30T09:41:41.009076+00:00', 'AI Software Engineer', 'Vietnam', 'Vielora - AI Chatbot SaaS Platform. Built RAG pipeline (Gemini + pgvector), multi-tenant architecture, async queues (Redis/BullMQ), payment integration.', 'End-to-end RAG with hybrid search (full-text + vector),Multi-tenant workspace + secured REST APIs (CORS, Rate Limiting, FingerprintJS),Async queues for crawl/index/cron email', 'work');
INSERT INTO experiences (id, company, role_vi, location_vi, start_date, end_date, is_current, description_vi, highlights_vi, technologies, sort_order, created_at, updated_at, role_en, location_en, description_en, highlights_en, type) VALUES (4, 'TITOPS VIETNAM CO., LTD. (Client: HVA Group)', 'Backend Engineer Intern', 'Việt Nam', '2025-11-01', '2026-01-01', false, 'Slice SocialFi - Nền tảng mạng xã hội Web3. Cross-chain token bridge, queue xử lý giao dịch bất đồng bộ, container hóa Docker/AWS EC2.', 'Cross-chain token bridge (BNB Smart Chain ↔ LensChain),Queue Redis xử lý giao dịch an toàn (DNPAY Fiat-to-Crypto),Container hóa microservices, deploy AWS EC2', 'Node.js,Hono,Viem,PostgreSQL,Supabase,Redis,Solidity,AWS EC2,Docker', 1, '2026-08-16T06:39:44.423112+00:00', '2026-09-30T09:41:40.42141+00:00', 'Backend Engineer Intern', 'Vietnam', 'Slice SocialFi - Web3 Social Network. Cross-chain token bridge, async transaction queues, Docker/AWS EC2 deployment.', 'Cross-chain token bridge (BNB Smart Chain ↔ LensChain),Redis queue for safe tx flows (DNPAY Fiat-to-Crypto),Docker microservices on AWS EC2', 'work');
INSERT INTO experiences (id, company, role_vi, location_vi, start_date, end_date, is_current, description_vi, highlights_vi, technologies, sort_order, created_at, updated_at, role_en, location_en, description_en, highlights_en, type) VALUES (5, 'TITOPS VIETNAM CO., LTD.', 'Full-stack Developer', 'Việt Nam', '2025-09-01', '2025-11-01', false, 'Giftcards - Giải pháp quà tặng doanh nghiệp. Tích hợp cổng thanh toán DNPAY, tối ưu luồng đặt hàng.', 'Tích hợp gateway DNPAY Merchant,Cải thiện luồng đặt hàng + tính năng retry thanh toán', 'NestJS,MongoDB,Redis,ReactJS', 2, '2026-08-16T06:39:44.423112+00:00', '2026-09-30T09:41:40.738861+00:00', 'Full-stack Developer', 'Vietnam', 'Giftcards - Corporate Gift Solution. DNPAY payment integration, order flow optimization.', 'DNPAY Merchant gateway integration,Order flow optimization + payment retry feature', 'work');
